import 'dart:convert';
import 'dart:typed_data';
import 'package:avelune_converter_core/avelune_converter_core.dart';

List<int> hex(String value) => [
  for (var i = 0; i < value.length; i += 2)
    int.parse(value.substring(i, i + 2), radix: 16),
];

void main() {
  final graph = const MarshalDecoder().decode(hex('04085b064000'));
  if (graph.node(graph.rootId).elements.single != graph.rootId) {
    throw StateError('Cycle was not preserved.');
  }
  final number = const MarshalDecoder().decode(hex(
    '0408661f312e37393736393331333438363233313537652b33303800ffff'));
  final bits = ByteData(8)..setFloat64(
    0, number.node(number.rootId).floatValue!, Endian.little);
  if (bits.getUint32(0, Endian.little) != 0xffffffff ||
      bits.getUint32(4, Endian.little) != 0x7fefffff) {
    throw StateError('Maximum finite float was not restored.');
  }
  final tableGraph = const MarshalDecoder().decode(hex(
    '0408753a0a5461626c653d0300000003000000020000000300000012000000ffff0000010009000a000b006300640065006d006e006f00c700c800c900d100d200d300'));
  final table = const TableDecoder().decode(tableGraph.node(tableGraph.rootId));
  for (var z = 0; z < 3; z++) {
    for (var y = 0; y < 2; y++) {
      for (var x = 0; x < 3; x++) {
        if (table.valueAt(x, y, z) != 100 * z + 10 * y + x - 1) {
          throw StateError('Table axes changed.');
        }
      }
    }
  }
  final decoded = const BoundedZlibDecoder().decode(hex(
    '780105c10104000000001000000000000000000100000000000000000000000000000000000000000000800800420042'));
  if (decoded.length != 1 || decoded.single != 65) {
    throw StateError('Empty distance tree was refused.');
  }
  print(jsonEncode({'cycle': true, 'maxFiniteExact': true,
    'tableCells': table.cellCount, 'zlibByte': decoded.single}));
}

